import React, { useEffect, useState } from 'react'
import { fetchPokemons } from '../data/pokemonData'
import { useRandomPokemon } from '../context/RandomPokemonContext'

function RandomPokemonImage() {
  const [pokemons, setPokemons] = useState([])
  const [imageUrl, setImageUrl] = useState('')
  const [loading, setLoading] = useState(true)

  const { randomIndex, rerollPokemon } = useRandomPokemon()

  useEffect(() => {
    const getPokemonData = async () => {
      try {
        const data = await fetchPokemons()
        setPokemons(data)

        // If randomIndex is null, generate it
        if (randomIndex === null) {
          rerollPokemon(data.length)
        }
      } catch (error) {
        console.error('Error fetching Pokémon:', error)
      } finally {
        setLoading(false)
      }
    }

    getPokemonData()
  }, [randomIndex, rerollPokemon])

  useEffect(() => {
    if (pokemons.length > 0 && randomIndex !== null) {
      const randomPokemon = pokemons[randomIndex]
      const fullImageUrl = `http://localhost:3000${randomPokemon.imageUrl.replace(
        '../',
        '/'
      )}`
      setImageUrl(fullImageUrl)
    }
  }, [pokemons, randomIndex])

  return (
    <div className='p-8'>
      {loading ? (
        <p>Loading Pokémon...</p>
      ) : imageUrl ? (
        <img
          src={imageUrl}
          alt='Random Pokémon'
          style={{ width: '100px', height: '100px', objectFit: 'cover' }}
        />
      ) : (
        <p>No Pokémon data available</p>
      )}
    </div>
  )
}

export default RandomPokemonImage
